<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {AbilityStudy,ABILITY_STUDIES,SHIP_EFFECT_AUDIT,type AbilityKind} from './ability-studies/effect.ts';
import {SHIP_DEFINITIONS} from '../ship-definitions.ts';
import {oceanMaterial} from '../scene/ocean.ts';
import {disposeTree} from '../scene/resources.ts';
const selected=ref<AbilityKind>('smoke'),category=ref('全部'),host=ref<HTMLElement|null>(null),playing=ref(true),loop=ref(true),speed=ref(1),time=ref(0),ready=ref(false),error=ref(''),top=ref(false);
const active=computed(()=>ABILITY_STUDIES.find(s=>s.id===selected.value)!),filtered=computed(()=>ABILITY_STUDIES.filter(s=>category.value==='全部'||s.group===category.value));
const phase=computed(()=>active.value.phases[time.value<1.8?0:time.value<5.7?1:2]);
let renderer:THREE.WebGLRenderer|undefined,controls:OrbitControls|undefined,observer:ResizeObserver|undefined,fx:AbilityStudy|undefined,elapsed=0;
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(-6,6,4,-4,.01,100),clock={value:0};
function choose(id:AbilityKind){selected.value=id;fx?.dispose();fx=new AbilityStudy(id);scene.add(fx.root);elapsed=0;time.value=0;if(matchMedia('(prefers-reduced-motion: reduce)').matches){peak();}else playing.value=true;}
function effectNames(ids:readonly AbilityKind[]){return ids.map(id=>ABILITY_STUDIES.find(s=>s.id===id)!.name).join(' · ')||'基础武器命中特效';}
function restart(){elapsed=0;time.value=0;playing.value=true;}
function toggle(){if(elapsed>=active.value.duration)restart();else playing.value=!playing.value;}
function peak(){elapsed=active.value.peak;time.value=elapsed;playing.value=false;}
function scrub(e:Event){elapsed=Number((e.target as HTMLInputElement).value);time.value=elapsed;playing.value=false;}
function view(overhead=false){top.value=overhead;camera.zoom=1;camera.position.set(overhead?0:4,overhead?13:7,overhead?.01:10);controls?.target.set(0,.4,0);camera.lookAt(0,.4,0);controls?.update();camera.updateProjectionMatrix();}
function resize(){if(!renderer||!host.value)return;const w=host.value.clientWidth,h=host.value.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);const half=Math.max(3.6,4.8/(w/h));camera.left=-half*w/h;camera.right=half*w/h;camera.top=half;camera.bottom=-half;camera.updateProjectionMatrix();controls!.enableRotate=w>600;renderer.domElement.style.touchAction=w>600?'none':'pan-y';}
onMounted(()=>{try{
 renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x102831);renderer.domElement.setAttribute('aria-label','舰船特殊能力三维特效');renderer.domElement.setAttribute('role','img');host.value!.prepend(renderer.domElement);
 const sea=new THREE.Mesh(new THREE.PlaneGeometry(40,40),oceanMaterial(clock,0x164257,.9));sea.rotation.x=-Math.PI/2;sea.position.y=-.05;scene.add(sea);
 controls=new OrbitControls(camera,renderer.domElement);controls.enablePan=false;controls.enableDamping=true;controls.minZoom=.7;controls.maxZoom=1.8;controls.maxPolarAngle=1.35;view();
 choose(selected.value);observer=new ResizeObserver(resize);observer.observe(host.value!);resize();let last=0,published=0;
 renderer.setAnimationLoop(now=>{const delta=last?Math.min((now-last)/1000,.06):0;last=now;if(playing.value){elapsed+=delta*speed.value;if(elapsed>=active.value.duration){if(loop.value)elapsed%=active.value.duration;else{elapsed=active.value.duration;playing.value=false;}}}if(now-published>45){time.value=elapsed;published=now;}clock.value=elapsed;fx?.seek(elapsed);controls!.update();renderer!.render(scene,camera);});
 ready.value=true;renderer.domElement.dataset.abilityReady='true';
}catch(e){error.value=e instanceof Error?e.message:String(e);}});
onBeforeUnmount(()=>{renderer?.setAnimationLoop(null);observer?.disconnect();controls?.dispose();fx?.dispose();disposeTree(scene);renderer?.dispose();});
